"  const handleDelete = async (id: string, title: string) => {
    if (Platform.OS === 'web') {
      const confirmed = typeof window !== 'undefined' && window.confirm(`Are you sure you want to delete "${title}"?`);
      if (confirmed) {
        await HapticsService.heavy();
        await LeadsRepository.deleteList(id);
        loadLists();
      }
      return;
    }

    Alert.alert('Delete List', `Are you sure you want to delete "${title}"?`, [
      { text: 'Cancel', style: 'cancel' },
      {
        text: 'Delete',
        style: 'destructive',
        onPress: async () => {
          await HapticsService.heavy();
          await LeadsRepository.deleteList(id);
          loadLists();
        },
      },
    ]);
  };

  const handleRecycleList = async (listId: string, title: string) => {
    await HapticsService.medium();

    const doRecycle = async () => {
      await HapticsService.success();
      const db = await import('../db/database').then((m) => m.getDatabase());
      await db.runAsync(
        `UPDATE leads 
         SET last_disposition = 'pending' 
         WHERE list_id = ? AND last_disposition IN ('no_answer', 'voicemail')`,
        [listId]
      );
      loadLists();
    };

    if (Platform.OS === 'web') {
      const confirmed = typeof window !== 'undefined' && window.confirm(`Recycle unanswered leads in "${title}" for next attempt?`);
      if (confirmed) {
        await doRecycle();
      }
      return;
    }

    Alert.alert(
      'Recycle Unanswered Leads for Next Attempt?',
      `This will reset leads in "${title}" that did not connect so you can run the next call cadence attempt.`,
      [
        { text: 'Cancel', style: 'cancel' },
        {
          text: 'Recycle for Attempt',
          onPress: doRecycle,
        },
      ]
    );
  };"

